import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosPersonaMark, KozmosPersonaMarkGroup } from "../../index";
import { KozmosCheckbox } from "../../react-bridge";

/**
 * Vue's PersonaMark and PersonaMarkGroup: the stories React's has, with the
 * same names and args, each inside the KozmosThemeProvider the Storybook's
 * decorator gives every story. test/parity draws each of React's in both
 * and holds Vue's render to React's. Generated by `port PersonaMark`;
 * Group and InAPersonaList written by hand. React's Text and Label are not
 * ported yet: these draw the element and classes each draws, and the
 * persona list's checkboxes are React's own, through the bridge.
 */
type Args = Record<string, unknown>;

// Pointr Cloud's personas and their colours: product data, as a site holds it.
const PERSONAS = [
  { name: "Customer", color: "#FF9800" },
  { name: "Visitor", color: "#2196F3" },
  { name: "Staff", color: "#4CAF50" },
];

const meta: Meta<Args> = {
  title: "Vue/Core/Data display/PersonaMark",
  component: KozmosPersonaMark,
  parameters: { layout: "padded" },
  args: { color: "#FF9800" },
  argTypes: { color: { control: "color" } },
  render: (args) => ({
    setup: () => () => h(KozmosPersonaMark, args as { color: string }),
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {};

/** Standing alone, the mark is an image named by the persona. */
export const Named: Story = {
  args: { color: "#2196F3", name: "Visitor" },
};

/**
 * The personas a tree row is visible to: one image, read "Assigned personas:
 * Customer, Visitor, Staff".
 */
export const Group: Story = {
  render: () => ({
    components: { KozmosPersonaMarkGroup },
    setup: () => ({ personas: PERSONAS }),
    template: `
      <div class="flex items-center gap-2">
        <p class="kozmos-reset kozmos-text kozmos-text-sm kozmos-text-normal kozmos-text-start kozmos-text-default">Gate A12</p>
        <KozmosPersonaMarkGroup :personas="personas" />
      </div>
    `,
  }),
};

/**
 * The feature panel's persona visibility list (GAP-106): each checkbox's
 * label is the persona's mark and name, read as the name alone.
 */
export const InAPersonaList: Story = {
  render: () => ({
    components: { KozmosCheckbox, KozmosPersonaMark },
    setup: () => ({ personas: PERSONAS }),
    template: `
      <div class="flex flex-col gap-2">
        <div v-for="(persona, index) in personas" :key="persona.name" class="flex items-center gap-2">
          <KozmosCheckbox
            :default-checked="index !== 1"
            :id="'persona-' + persona.name"
            wrapper-class-name="w-auto"
          />
          <label
            class="kozmos-reset kozmos-label flex items-center gap-2"
            :for="'persona-' + persona.name"
          >
            <KozmosPersonaMark :color="persona.color" />
            {{ persona.name }}
          </label>
        </div>
      </div>
    `,
  }),
};
